head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldbnf50100";
scwin.dmenus = undefined;
scwin.fm = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        scwin.init_datefmt_cal_efReqStartDt();
        scwin.init_datefmt_cal_efReqEndDt();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldbnf50100.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb0", fn: function () { return String(String((dma_pageContext.get("saleInstNm") ?? ""))); } },
        { childId: "__rb1", fn: function () { return String(String((dma_pageContext.get("saleIsuNm") ?? ""))); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_datefmt_cal_efReqStartDt
 * @description 초기화 — datefmt cal ef Req Start Dt
 * @returns {void}
 * @hidden N
 */
scwin.init_datefmt_cal_efReqStartDt = function () { $c.date.checkCalendarFormat("cal_efReqStartDt", "yyyyMMdd"); };

/**
 * @method
 * @name init_datefmt_cal_efReqEndDt
 * @description 초기화 — datefmt cal ef Req End Dt
 * @returns {void}
 * @hidden N
 */
scwin.init_datefmt_cal_efReqEndDt = function () { $c.date.checkCalendarFormat("cal_efReqEndDt", "yyyyMMdd"); };

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        scwin.dmenus = { "bmenu": 1, "mmenu": 0 };
        $('div#header').trigger('mouseleave');

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf50100.onpageload' }); }
};

// [A] 초기 목록 미해결 — 자기 목록을 채우는 tx 가 4개다(tx_fn_searchList, tx_OpenReqView, tx_OpenRetView, tx_PopUp_FeeCal) — 어느 것이 «열자마자» 인지 정할 근거가 없다

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_searchList_onclick
 * @description btn_searchList 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_searchList_onclick = async function(e){
    try {
        await scwin.searchList()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf50100.btn_searchList_onclick' }); }
};

/**
 * @method
 * @name cal_efReqStartDt_onfocus
 * @description cal_efReqStartDt 포커스 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.cal_efReqStartDt_onfocus = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        Del_Hypen(selfVar);select();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf50100.cal_efReqStartDt_onfocus' }); }
};

/**
 * @method
 * @name cal_efReqEndDt_onfocus
 * @description cal_efReqEndDt 포커스 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.cal_efReqEndDt_onfocus = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        Del_Hypen(selfVar);select();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf50100.cal_efReqEndDt_onfocus' }); }
};

/**
 * @method
 * @name grd_result_oncellclick
 * @description grd_result 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_result_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_result');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_result */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (r["applYn"] === '반송') { await scwin.OpenRetView(r["bndApplId"], r["bndListProcsTpCd"], r["bndMktactTpCd"], r["bkbndTpCd"]); return; }
        await scwin.OpenReqView(r["bndApplId"], "1", "320", ""); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_result.oncellclick' });
    }
};

/**
 * @method
 * @name krxpage_pagenavigator_94_onclick
 * @description krxpage_pagenavigator_94 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_94_onclick = async function (index) {
    try {
        const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index;
        $c.util.getComponent('dma_searchListReq').set('pageIndex', pi);
        await scwin.searchList();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldbnf50100.krxpage_pagenavigator_94_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_searchList
 * @description search List 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_searchList = async function () {
    const sbmOptions = {
        id: "tx_fn_searchList",
        method: "post",
        action: "/sales/sales.do",
        ref: "dma_searchListReq",
        target: "dlt_result=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_OpenReqView
 * @description Open Req View 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
