 */
scwin.tx_OpenRetView = async function () {
    const sbmOptions = {
        id: "tx_OpenRetView",
        method: "post",
        action: "/result/result.do",
        ref: "dma_OpenRetViewReq",
        target: "dlt_result=body.content",
