/**
 * @method
 * @name tx_PopUp_FeeCal
 * @description Pop Up Fee Cal 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_PopUp_FeeCal = async function () {
    const sbmOptions = {
