///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name initPageIndex
 * @description init Page Index 처리
 * @returns {void}
 * @hidden N
 */
scwin.initPageIndex = function () {
    $c.util.getComponent('dma_searchListReq').set('pageIndex', "1");
};

/**
 * @method
 * @name grd_result_fmt_applYn
 * @description grd result fmt appl Yn 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_result_fmt_applYn = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_result");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "applYn") ?? '') : '');
        if (v === '반송') { return '<a href="javascript:void(0)"' + (true ? ' class="lnk"' : '') + '>' + String((dl && dl.getCellData ? dl.getCellData(r, "applYn") : '') ?? '') + '</a>'; }
        return String((dl && dl.getCellData ? dl.getCellData(r, "applYn") : '') ?? '');
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_result.applYn" }); return String(data ?? ''); }
};

/**
 * @method
 * @name searchList
 * @description search List 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchList = async function () {
    const frm = (document.SearchForm || { elements: [] });
    $c.util.getComponent('dma_searchListReq').set('method', "salesReportRstList");
    frm.action = '/sales/sales.do';
    frm.target = '_self';
    await scwin.tx_fn_searchList();
};

/**
 * @method
 * @name OpenReqView
 * @description Open Req View 처리
 * @param {*} bnd_appl_id bnd_appl_id
 * @param {*} bnd_list_procs_tp_cd bnd_list_procs_tp_cd
 * @param {*} bnd_mktact_tp_cd bnd_mktact_tp_cd
 * @param {*} bkbnd_tp_cd bkbnd_tp_cd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.OpenReqView = async function (bnd_appl_id, bnd_list_procs_tp_cd, bnd_mktact_tp_cd, bkbnd_tp_cd) {
    scwin.fm = (document.SearchForm || { elements: [] });
    const width = 900;
    const height = 660;
    const mtWidth = document.body.clientWidth;
    const mtHeight = document.body.clientHeight;
    const scX = 0;
    const scY = 0;
    const popX = scX + (mtWidth - width) / 2;
    const popY = scY + (mtHeight - height) / 2;
    let _previewWindow;
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    _previewWindow = (function(){ throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + "/sales/sales.do", unresolved: "nav:" + "/sales/sales.do" }; })();
    $c.util.getComponent("dma_searchListReq").set("bndApplId", bnd_appl_id);
    $c.util.getComponent("dma_searchListReq").set("bndListProcsTpCd", bnd_list_procs_tp_cd);
    $c.util.getComponent("dma_searchListReq").set("bndMktactTpCd", bnd_mktact_tp_cd);
    $c.util.getComponent('dma_searchListReq').set('method', 'salesReportRstView');
    scwin.fm.action = '/sales/sales.do';

};

/**
 * @method
 * @name OpenRetView
 * @description Open Ret View 처리
 * @param {*} bnd_appl_id bnd_appl_id
 * @param {*} bnd_list_procs_tp_cd bnd_list_procs_tp_cd
 * @param {*} bnd_mktact_tp_cd bnd_mktact_tp_cd
 * @param {*} bkbnd_tp_cd bkbnd_tp_cd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.OpenRetView = async function (bnd_appl_id, bnd_list_procs_tp_cd, bnd_mktact_tp_cd, bkbnd_tp_cd) {
    scwin.fm = (document.SearchForm || { elements: [] });
    const width = 450;
    const height = 250;
    const mtWidth = document.body.clientWidth;
    const mtHeight = document.body.clientHeight;
    const scX = 0;
    const scY = 0;
    const popX = scX + (mtWidth - width) / 2;
    const popY = scY + (mtHeight - height) / 2;
    let _previewWindow;
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    _previewWindow = (function(){ throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + "/result/result.do", unresolved: "nav:" + "/result/result.do" }; })();
    $c.util.getComponent("dma_searchListReq").set("bndApplId", bnd_appl_id);
    $c.util.getComponent("dma_searchListReq").set("bndListProcsTpCd", bnd_list_procs_tp_cd);
    $c.util.getComponent("dma_searchListReq").set("bndMktactTpCd", bnd_mktact_tp_cd);
    $c.util.getComponent("dma_searchListReq").set("bkbndTpCd", bkbnd_tp_cd);
    $c.util.getComponent('dma_searchListReq').set('method', 'returnView');
    scwin.fm.action = '/result/result.do';

};

/**
 * @method
 * @name PopUp_FeeCal
 * @description Pop Up Fee Cal 처리
 * @param {*} bnd_appl_id bnd_appl_id
 * @param {*} bnd_list_procs_tp_cd bnd_list_procs_tp_cd
 * @param {*} bnd_mktact_tp_cd bnd_mktact_tp_cd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.PopUp_FeeCal = async function (bnd_appl_id, bnd_list_procs_tp_cd, bnd_mktact_tp_cd) {
    scwin.fm = (document.SearchForm || { elements: [] });
    const width = 690;
